begin;
select plan(29);
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select '00000000-0000-0000-0000-000000000000',id,'authenticated','authenticated',id||'@example.invalid','{}','{}',now(),now()from unnest(array['19000000-0000-4000-8000-000000000001'::uuid,'19000000-0000-4000-8000-000000000002','19000000-0000-4000-8000-000000000003','19000000-0000-4000-8000-000000000004'])id;
update public.profiles set full_name=case id when '19000000-0000-4000-8000-000000000001' then 'Manager' else 'Supervisor '||right(id::text,1)end,must_change_password=false where id::text like'19000000-%';
insert into public.organizations(id,name,slug)values('29000000-0000-4000-8000-000000000001','Phase4 A','phase4-a'),('29000000-0000-4000-8000-000000000002','Phase4 B','phase4-b');
insert into public.branches(id,organization_id,name,code,timezone)values('39000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','A1','A1','Asia/Riyadh'),('39000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','A2','A2','UTC'),('39000000-0000-4000-8000-000000000003','29000000-0000-4000-8000-000000000002','B1','B1','UTC');
insert into public.organization_memberships values('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','organization_manager',now(),now());
insert into public.branch_memberships(branch_id,user_id,role)values('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000002','branch_manager'),('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000003','branch_manager'),('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000004','staff');
insert into public.branch_supervisor_teams(id,organization_id,branch_id,supervisor_user_id)values('49000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000002'),('49000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000003');
insert into public.operational_staff(id,organization_id,branch_id,display_name,created_by)values('59000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','Eligible One','19000000-0000-4000-8000-000000000002'),('59000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','Day Off','19000000-0000-4000-8000-000000000002');
insert into public.operational_staff_assignments(id,organization_id,branch_id,operational_staff_id,supervisor_team_id,operational_roles)values('69000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',array['kitchen']),('69000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000001',array['cleaner']);
insert into public.operational_staff_duty_statuses(organization_id,branch_id,operational_staff_id,assignment_id,duty_date,duty_status,set_by)values('29000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000002',private.phase4a_business_date('Asia/Riyadh'),'day_off','19000000-0000-4000-8000-000000000002');

select lives_ok($$select public.save_phase4a_hygiene_draft('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"pass","fingernails":"pending","hair":"issue","facial_hair":"pending","remark":""}]')$$,'incomplete hygiene draft saves');
select is((select count(*)from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='draft'),1::bigint,'one draft row');
select is((select count(*)from public.hygiene_staff_snapshots h join public.checklist_submissions s on s.id=h.submission_id where s.organization_id='29000000-0000-4000-8000-000000000001' and s.branch_id='39000000-0000-4000-8000-000000000001' and s.supervisor_team_id='49000000-0000-4000-8000-000000000001' and s.checklist_type='staff_hygiene'),1::bigint,'only eligible staff snapshot drafted');
select throws_ok($$select public.save_phase4a_hygiene_draft('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"pass","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":""},{"staff_id":"59000000-0000-4000-8000-000000000002","uniform":"pass","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":""}]')$$,'22023','staff set changed','day-off identity is rejected from the effective team roster');
select lives_ok($$select public.save_phase4a_hygiene_draft('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"issue","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":"draft"}]')$$,'same draft upserts');
select is((select count(*)from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='draft'),1::bigint,'upsert has no duplicate');
select is((public.get_operational_team_hygiene_current_state('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001',(select id from public.branch_operational_teams where legacy_supervisor_team_id='49000000-0000-4000-8000-000000000001'))->>'state'),'draft','current state reports draft');
select is(jsonb_array_length(public.get_operational_team_hygiene_current_state('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001',(select id from public.branch_operational_teams where legacy_supervisor_team_id='49000000-0000-4000-8000-000000000001'))->'staff'),1,'current state reconciles roster');
select is((public.get_operational_team_hygiene_current_state('19000000-0000-4000-8000-000000000003','39000000-0000-4000-8000-000000000001',(select id from public.branch_operational_teams where legacy_supervisor_team_id='49000000-0000-4000-8000-000000000002'))->>'state'),'none','same-branch other Supervisor sees only their own team state');
select throws_ok($$select public.get_operational_team_hygiene_current_state('19000000-0000-4000-8000-000000000004','39000000-0000-4000-8000-000000000001',(select id from public.branch_operational_teams where legacy_supervisor_team_id='49000000-0000-4000-8000-000000000001'))$$,'42501','hygiene access denied','legacy Staff denied');
select lives_ok($$select public.submit_phase4a_hygiene('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','79000000-0000-4000-8000-000000000001',repeat('a',64),'[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"issue","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":" Needs correction "}]')$$,'hygiene final submits');
select is((select count(*)from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='submitted'),1::bigint,'exactly one final');
select is((select count(*)from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='draft'),0::bigint,'final removes draft');
select is((select count(*)from public.checklist_issues i join public.checklist_submissions s on s.id=i.source_submission_id where s.organization_id='29000000-0000-4000-8000-000000000001' and s.branch_id='39000000-0000-4000-8000-000000000001' and s.supervisor_team_id='49000000-0000-4000-8000-000000000001' and s.checklist_type='staff_hygiene'),1::bigint,'exactly one atomic issue');
select lives_ok($$select public.submit_phase4a_hygiene('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','79000000-0000-4000-8000-000000000001',repeat('a',64),'[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"issue","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":" Needs correction "}]')$$,'identical replay returns final');
select is((select count(*)from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='submitted'),1::bigint,'replay remains exactly once');
select throws_ok($$select public.submit_phase4a_hygiene('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','79000000-0000-4000-8000-000000000001',repeat('b',64),'[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"issue","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":"changed"}]')$$,'23505','idempotency conflict','same key different hash conflicts');
select throws_ok($$select public.submit_phase4a_hygiene('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','79000000-0000-4000-8000-000000000002',repeat('c',64),'[{"staff_id":"59000000-0000-4000-8000-000000000001","uniform":"pass","fingernails":"pass","hair":"pass","facial_hair":"pass","remark":""}]')$$,'23505',null,'different key cannot duplicate final');
select throws_ok($$update public.checklist_submissions set branch_name_snapshot='Changed' where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='submitted'$$,'55000','submitted report is immutable','final parent immutable');
select throws_ok($$update public.hygiene_staff_snapshots set display_name_snapshot='Changed' where submission_id in(select id from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='submitted')$$,'55000','submitted report is immutable','hygiene child immutable');
update public.operational_staff set display_name='Renamed',employment_status='inactive',deactivated_at=now(),deactivated_by='19000000-0000-4000-8000-000000000001' where id='59000000-0000-4000-8000-000000000001';update public.operational_staff_assignments set active=false,valid_to=current_date where id='69000000-0000-4000-8000-000000000001';
select is((select h.display_name_snapshot from public.hygiene_staff_snapshots h join public.checklist_submissions s on s.id=h.submission_id where s.organization_id='29000000-0000-4000-8000-000000000001' and s.branch_id='39000000-0000-4000-8000-000000000001' and s.supervisor_team_id='49000000-0000-4000-8000-000000000001' and s.checklist_type='staff_hygiene' and h.operational_staff_id='59000000-0000-4000-8000-000000000001'),'Eligible One','historical name snapshot unchanged');
select is(jsonb_array_length(public.get_phase4a_report_detail('19000000-0000-4000-8000-000000000001',(select id from public.checklist_submissions where organization_id='29000000-0000-4000-8000-000000000001' and branch_id='39000000-0000-4000-8000-000000000001' and supervisor_team_id='49000000-0000-4000-8000-000000000001' and checklist_type='staff_hygiene' and state='submitted'),true)->'staff'),1,'Manager reads history after staff inactive');
select is((public.list_phase4a_managed_issues('19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001',1,1,null,null,null,null,null,'staff_hygiene',null,null)->>'total')::int,1,'submitted hygiene issue total independent of limit');
select is(jsonb_array_length(public.list_phase4a_managed_issues('19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001',1,1,null,null,null,null,null,'staff_hygiene',null,null)->'issues'),1,'submitted hygiene issue SQL limit applied');
select throws_ok($$select public.list_phase4a_managed_issues('19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001',1,51)$$,'42501','issue access denied','issue page size bounded');
update public.profiles set disabled_at=now()where id='19000000-0000-4000-8000-000000000002';
select throws_ok($$select public.get_phase4a_current_state('19000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','kitchen_opening')$$,'42501','state denied','disabled Supervisor denied');
select is(has_function_privilege('authenticated','public.save_phase4a_hygiene_draft(uuid,uuid,jsonb)','execute'),false,'authenticated cannot execute hygiene mutation');
select is(has_function_privilege('service_role','public.save_phase4a_hygiene_draft(uuid,uuid,jsonb)','execute'),true,'service role executes intended hygiene RPC');
select ok(not has_table_privilege('anon','public.checklist_submissions','truncate')and not has_table_privilege('authenticated','public.checklist_submissions','delete')and not has_table_privilege('anon','public.checklist_submissions','delete'),'no broad truncate/delete grants');
select * from finish();rollback;
